/* ===== 顔ウォール =====
   13年分の写真から集めた顔を並べ、クリックするとその人の写真が出る。
   顔の照合はしない（アーカイブの顔は中央値66pxで、照合すると他人が出るため）。
   クリックした顔と写真の対応は確定情報なので、外れることがない。 */
(function(){
 try{
  var wrap=document.getElementById('facewrap');
  var grid=document.getElementById('wallgridf');
  var out=document.getElementById('faceout');
  if(!wrap||!grid||!out)return;
  fetch('wall.json',{cache:'no-store'}).then(function(r){return r.json();}).then(function(W){
   if(!W||!W.people||!W.people.length)return;
   wrap.hidden=false;
   grid.style.setProperty('--wg',W.grid);
   var cur=-1;
   W.people.forEach(function(pe,i){
    var b=document.createElement('button');
    b.type='button';
    b.className='ft wt-'+i;
    b.setAttribute('aria-pressed','false');
    b.setAttribute('aria-label',(pe.y?pe.y+'　':'')+pe.n+'枚の写真に写っている人');
    b.addEventListener('click',function(){ open_(i,b); });
    grid.appendChild(b);
   });
   function open_(i,btn){
    grid.querySelectorAll('.ft[aria-pressed="true"]').forEach(function(x){
     x.setAttribute('aria-pressed','false');});
    if(cur===i){ cur=-1; out.hidden=true; out.innerHTML=''; return; }
    cur=i; btn.setAttribute('aria-pressed','true');
    var pe=W.people[i];
    var h=document.createElement('div'); h.className='faceout-h';
    var bb=document.createElement('b'); bb.textContent='この人が写っている写真　'+pe.n+'枚';
    h.appendChild(bb);
    if(pe.y){ var yy=pe.y.split('-');
              var sp=document.createElement('span');
              sp.textContent=(yy[0]===yy[1]?yy[0]:yy[0]+'〜'+yy[1])+'年';
              h.appendChild(sp); }
    var x=document.createElement('button'); x.type='button'; x.className='fo-x';
    x.setAttribute('aria-label','閉じる'); x.textContent='×';
    x.addEventListener('click',function(){ open_(i,btn); });
    h.appendChild(x);
    var g=document.createElement('div'); g.className='gallery';
    pe.p.forEach(function(id){
     var im=document.createElement('img');
     im.loading='lazy'; im.decoding='async'; im.alt='';
     im.src='wall/t'+id+'.jpg';
     im.dataset.full='wall/g'+id+'.jpg';
     g.appendChild(im);
    });
    out.innerHTML=''; out.appendChild(h); out.appendChild(g); out.hidden=false;
    out.scrollIntoView({behavior:'smooth',block:'nearest'});
   }
  }).catch(function(){});
 }catch(e){}
})();


/* ===== ページ全体を斜めの帯にして、その軸上を進む =====
   画面上の位置 = T + R(A)・P。P=(列幅/2, s) が画面中央に来るように T を決める。
   s はスクロール量そのものなので、ふつうに縦スクロールするだけで
   視点が斜めに進んでいく。ホイールは乗っ取らない。 */
(function(){
 try{
  var track=document.getElementById('track'), world=document.getElementById('world');
  if(!track||!world) return;
  var rm=matchMedia('(prefers-reduced-motion: reduce)');
  var A=0,cosA=1,sinA=0,cw=1040,H=0,vw=0,vh=0,ready=false;

  function layout(){
   if(rm.matches){ track.style.height=''; world.style.transform=''; ready=false; return; }
   vw=innerWidth; vh=innerHeight;
   /* 狭い画面ほど角度を寝かせる。でないと列が細くなりすぎて読めない */
   var deg = vw<760 ? 6 : (vw<1100 ? 9 : 12);
   A=-deg*Math.PI/180;               /* 右下へ進む向き */
   cosA=Math.cos(A); sinA=Math.sin(A);
   document.documentElement.style.setProperty('--ang',deg+'deg');
   /* 回しても画面に収まる列幅 */
   var pad = vw<760 ? 12 : 24;
   var w = (vw-pad*2 - vh*Math.abs(sinA))/Math.abs(cosA);
   cw = Math.max(238, Math.min(1040, w));
   world.style.setProperty('--cw', cw.toFixed(0)+'px');
   H = world.offsetHeight;
   track.style.height = (H+vh)+'px';
   ready=true;
  }
  var FORCE=null;                     /* 検証用: s を直接与える */
  /* 表示位置は実スクロールへ遅れて追従する（慣性）。
     スクロールそのものは乗っ取らない＝スクロールバー・キーボード・
     アンカー移動・ブラウザ標準の慣性を壊さない。見え方だけを遅らせる。 */
  var EASE=0.12, cur=null, iraf=0, lastT=0, driftT=0, gen=0, itim=0;
  /* 次の1コマを要求する。rAFが来ない環境（描画が要求されないヘッドレス等）でも
     止まらないよう、タイマーも併走させ、先に来たほうだけを通す */
  function nextFrame(fn){
   var g=++gen;
   function once(ts){
    if(g!==gen) return;
    gen++;                       /* 相方を無効化 */
    if(itim){ clearTimeout(itim); itim=0; }
    fn(ts);
   }
   iraf=requestAnimationFrame(once);
   itim=setTimeout(function(){ once(); }, 16);
  }
  function targetS(){ return (FORCE===null?scrollY:FORCE)+vh/2; }
  function draw(s){
   var px=cw/2;
   var tx=vw/2-(cosA*px-sinA*s), ty=vh/2-(sinA*px+cosA*s);
   world.style.transform='translate3d('+tx.toFixed(1)+'px,'+ty.toFixed(1)+'px,0) rotate('+(A*180/Math.PI).toFixed(2)+'deg)';
   window.__worldS=s;               /* 街の描画が同じ位置を使えるように */
  }
  function apply(){                  /* 即時（初期化・リサイズ・検証用） */
   if(!ready) return;
   cur=targetS(); draw(cur);
  }
  function ease(ts){
   iraf=0;
   if(!ready) return;
   var now=(typeof ts==='number')?ts:(performance&&performance.now?performance.now():Date.now());
   var dt=lastT?Math.min(Math.max(now-lastT,1),200):16.7;   /* フレームが飛んでも破綻させない */
   lastT=now;
   var tg=targetS();
   if(cur===null){ cur=tg; }
   var d=tg-cur;
   if(Math.abs(d)<0.05){ cur=tg; draw(cur); lastT=0; driftT=0; return; }
   /* 経過時間ぶんだけ詰める。60fps換算で1フレームEASE%と同じ速さになる */
   var k=1-Math.pow(1-EASE, dt/16.7);
   cur+=d*k;
   driftT+=dt;
   if(driftT>600){ cur=tg; }        /* 追従が長引いたら吸着（取り残されない保険） */
   draw(cur);
   nextFrame(ease);
  }
  function onScroll(){
   if(rm.matches){ apply(); return; }   /* 動きを減らす設定では即時 */
   driftT=0;
   if(!iraf){ lastT=0; nextFrame(ease); }
  }

  /* 検証用: ?wy=<scrollY> でその位置を同期で描く */
  var _wy=new URLSearchParams(location.search).get('wy');

  function boot(){
   layout();
   if(_wy!==null) FORCE=+_wy;
   apply();
  }
  boot();
  addEventListener('scroll',onScroll,{passive:true});
  addEventListener('resize',function(){layout();apply();},{passive:true});
  addEventListener('load',boot);
  /* 画像が入って高さが変わるので測り直す */
  if(window.ResizeObserver){
   var ro=new ResizeObserver(function(){ if(!rm.matches){ H=world.offsetHeight;
     track.style.height=(H+vh)+'px'; apply(); } });
   ro.observe(world);
  }
  if(rm.addEventListener) rm.addEventListener('change',function(){layout();apply();});
  /* 見張り: scrollイベントもrAFも来ない環境（ヘッドレス・非表示タブ）でも
     表示が取り残されないようにする。ずれていたら起こすだけなので、
     通常のブラウザでは何もしない（負荷ゼロ） */
  setInterval(function(){
   if(!ready||rm.matches) return;
   var tg=targetS();
   if(cur===null||Math.abs(tg-cur)>0.5){
    if(!iraf){ lastT=0; nextFrame(ease); }
   }
  },250);
  /* 検証用: 慣性の追従曲線を、スクロールイベントに頼らず直接測る。
     ヘッドレスでは scroll も rAF も発火しないため、これが無いと実装を確かめられない */
  window.__easeProbe=function(toY,steps){
   if(!ready) layout();
   var save=FORCE, out=[];
   FORCE=toY; cur=(cur===null)?0+vh/2:cur; lastT=0; driftT=0;
   for(var i=0;i<steps;i++){
    var tg=targetS(), d=tg-cur;
    if(Math.abs(d)<0.05){ cur=tg; out.push(Math.round(cur)); break; }
    cur+=d*(1-Math.pow(1-EASE,1));
    out.push(Math.round(cur));
   }
   FORCE=save;
   return out;
  };
 }catch(e){}
})();


/* ===== 章のドット絵を立体にして回す（描画器は自前） =====
   平面のドット絵を奥行き方向に押し出し、Y軸で回してX軸で少し傾ける。
   遠近法はなし。裏向きの面は捨て、残りを奥から順に塗る。 */
(function(){
 try{
  if(!window.PXV||!window.PXPAL) return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var boxes=document.querySelectorAll('.pxbox[data-px]');
  if(!boxes.length) return;
  var c0=document.createElement('canvas');
  if(!c0.getContext||!c0.getContext('2d')) return;

  var DEPTH=6, TILT=0.22, DPR=Math.min(2,devicePixelRatio||1);
  var LX=-0.45, LY=-0.78, LZ=-0.44;   /* 光の向き（左上手前から） */

  function rgb(hex,f){
   var n=parseInt(hex.slice(1),16);
   var R=(n>>16)&255,G=(n>>8)&255,B=n&255;
   R=Math.min(255,Math.round(R*f));
   G=Math.min(255,Math.round(G*f));
   B=Math.min(255,Math.round(B*f));
   return 'rgb('+R+','+G+','+B+')';
  }
  /* 横に続く同じ色を1つの箱にまとめる */
  function build(rows){
   var w=0,i;
   for(i=0;i<rows.length;i++) if(rows[i].length>w) w=rows[i].length;
   var bs=[];
   for(var y=0;y<rows.length;y++){
    var row=rows[y];
    for(var x=0;x<row.length;){
     var ch=row.charAt(x);
     if(ch==='.'){x++;continue;}
     var k=1; while(x+k<row.length&&row.charAt(x+k)===ch) k++;
     bs.push([x,x+k,y,y+1,PXPAL[ch]||'#2C3B47']);
     x+=k;
    }
   }
   return {w:w,h:rows.length,bs:bs};
 }

  /* 箱の6面。[頂点4つ, 法線] を模型座標で返す */
  function faces(b){
   var x0=b[0],x1=b[1],y0=b[2],y1=b[3],z0=0,z1=DEPTH;
   return [
    [[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0]],[0,0,-1]],  /* 手前 */
    [[[x1,y0,z1],[x0,y0,z1],[x0,y1,z1],[x1,y1,z1]],[0,0,1]],   /* 奥   */
    [[[x0,y0,z1],[x0,y0,z0],[x0,y1,z0],[x0,y1,z1]],[-1,0,0]],  /* 左   */
    [[[x1,y0,z0],[x1,y0,z1],[x1,y1,z1],[x1,y1,z0]],[1,0,0]],   /* 右   */
    [[[x0,y0,z1],[x1,y0,z1],[x1,y0,z0],[x0,y0,z0]],[0,-1,0]],  /* 上   */
    [[[x0,y1,z0],[x1,y1,z0],[x1,y1,z1],[x0,y1,z1]],[0,1,0]]    /* 下   */
   ];
  }

  var items=[];
  for(var i=0;i<boxes.length;i++){
   var el=boxes[i], key=el.getAttribute('data-px'), rows=PXV[key];
   if(!rows) continue;
   var m=build(rows);
   var cv=document.createElement('canvas');
   cv.setAttribute('role','img');
   cv.setAttribute('aria-label',(el.querySelector('svg')&&el.querySelector('svg').getAttribute('aria-label'))||'');
   el.appendChild(cv); el.classList.add('on');
   items.push({el:el,cv:cv,ctx:cv.getContext('2d'),m:m,near:false,th:0});
  }
  if(!items.length) return;

  function resize(it){
   var cw=it.el.clientWidth||160;
   var ch=Math.round(cw*0.82);
   it.cv.style.height=ch+'px';
   it.cv.width=Math.round(cw*DPR); it.cv.height=Math.round(ch*DPR);
   it.cw=cw; it.chh=ch;
   var m=it.m;
   it.s=Math.min(cw/(m.w+DEPTH+2), ch/(m.h+DEPTH*0.9+2));
  }

  function draw(it){
   var ctx=it.ctx,m=it.m,S=it.s*DPR;
   var cw=it.cv.width, chh=it.cv.height;
   ctx.clearRect(0,0,cw,chh);
   var cT=Math.cos(it.th), sT=Math.sin(it.th);
   var cP=Math.cos(TILT), sP=Math.sin(TILT);
   var ox=m.w/2, oy=m.h/2, oz=DEPTH/2;
   function proj(p){
    var x=p[0]-ox, y=p[1]-oy, z=p[2]-oz;
    var X=x*cT+z*sT, Z=-x*sT+z*cT;
    var Y=y*cP-Z*sP, Z2=y*sP+Z*cP;
    return [X*S+cw/2, Y*S+chh/2, Z2];
   }
   var list=[];
   for(var i=0;i<m.bs.length;i++){
    var b=m.bs[i], fs=faces(b);
    for(var f=0;f<6;f++){
     var nrm=fs[f][1];
     /* 法線も同じ向きに回す */
     var nX=nrm[0]*cT+nrm[2]*sT, nZ=-nrm[0]*sT+nrm[2]*cT;
     var nY=nrm[1]*cP-nZ*sP, nZ2=nrm[1]*sP+nZ*cP;
     if(nZ2>=-0.001) continue;                 /* 裏向きは描かない */
     var q=fs[f][0], pts=[proj(q[0]),proj(q[1]),proj(q[2]),proj(q[3])];
     var zc=(pts[0][2]+pts[1][2]+pts[2][2]+pts[3][2])/4;
     var lam=-(nX*LX+nY*LY+nZ2*LZ);
     if(lam<0) lam=0;
     list.push([zc,pts,rgb(b[4],0.62+0.5*lam)]);
    }
   }
   list.sort(function(a,b){return b[0]-a[0];});   /* 奥から手前へ */
   for(var i=0;i<list.length;i++){
    var pts=list[i][1];
    ctx.beginPath();
    ctx.moveTo(pts[0][0],pts[0][1]);
    ctx.lineTo(pts[1][0],pts[1][1]);
    ctx.lineTo(pts[2][0],pts[2][1]);
    ctx.lineTo(pts[3][0],pts[3][1]);
    ctx.closePath();
    ctx.fillStyle=list[i][2];
    ctx.fill();
    ctx.strokeStyle=list[i][2];
    ctx.lineWidth=1; ctx.stroke();          /* 継ぎ目の隙間を埋める */
   }
  }

  var forced=new URLSearchParams(location.search).get('vox');
  function update(){
   for(var i=0;i<items.length;i++){
    var it=items[i];
    if(!it.near) continue;
    var r=it.el.getBoundingClientRect();
    var pr=(r.top+r.height/2)/(innerHeight||1);
    if(pr<0)pr=0; else if(pr>1)pr=1;
    it.th=(forced!==null)?(+forced):((0.5-pr)*1.10);
    draw(it);
   }
  }
  var raf=0;
  function sched(){ if(!raf) raf=requestAnimationFrame(function(){raf=0;update();}); }

  if(window.IntersectionObserver){
   var io=new IntersectionObserver(function(es){
    for(var i=0;i<es.length;i++){
     var it=es[i].target.__v; if(!it) continue;
     it.near=es[i].isIntersecting;
     if(it.near&&!it.sized){ resize(it); it.sized=true; }
    }
    sched();
   },{rootMargin:'40% 0px 40% 0px'});
   for(var i=0;i<items.length;i++){ items[i].el.__v=items[i]; io.observe(items[i].el); }
  }else{
   for(var i=0;i<items.length;i++){ items[i].near=true; resize(items[i]); items[i].sized=true; }
  }
  addEventListener('scroll',sched,{passive:true});
  addEventListener('resize',function(){
   for(var i=0;i<items.length;i++) if(items[i].sized) resize(items[i]);
   sched();
  },{passive:true});
  addEventListener('load',function(){
   for(var i=0;i<items.length;i++) if(items[i].near&&!items[i].sized){resize(items[i]);items[i].sized=true;}
   sched();
  });
  sched();
 }catch(e){}
})();


/* ===== 左右の街を立体にして回す =====
   街は縦に66,000px以上ある。そんなcanvasは作れないので、
   画面2つぶんの高さのcanvasを .world の中に置き、
   スクロールが進んだら置き直して描き直す。
   .world の中にあるので、ページの傾きと移動には自動でついてくる。 */
(function(){
 try{
  if(!window.TOWNV) return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var boxesL=document.querySelector('.twl'), boxesR=document.querySelector('.twr');
  if(!boxesL||!boxesR) return;
  var probe=document.createElement('canvas');
  if(!probe.getContext||!probe.getContext('2d')) return;

  var _q=new URLSearchParams(location.search);
  var DEPTH=4, TILT=0.20, DPR=Math.min(2,devicePixelRatio||1);
  var LX=-0.45, LY=-0.78, LZ=-0.44;
  var PAL=TOWNV.c;

  function rgb(hex,f,sat,fade){
   var v=parseInt(hex.slice(1),16);
   var R=((v>>16)&255)*f, G=((v>>8)&255)*f, B=(v&255)*f;
   if(sat!==undefined&&sat<1){
    var L=0.299*R+0.587*G+0.114*B;
    R=L+(R-L)*sat; G=L+(G-L)*sat; B=L+(B-L)*sat;
   }
   /* 奥ほど地の色に沈める。白地時代は紙の白(252)へ寄せていたので、
      黒地では奥ほど明るくなり遠近が逆転していた */
   if(fade){ R+=(13-R)*fade; G+=(13-G)*fade; B+=(13-B)*fade; }
   return 'rgb('+Math.min(255,Math.round(R))+','+Math.min(255,Math.round(G))+','+Math.min(255,Math.round(B))+')';
  }
  /* 絵ごとに、横に続く同じ色をまとめた箱の並びを作る */
  /* 同じ色のかたまりを、横だけでなく縦にもまとめる。
     塗る面の数がおよそ半分になり、スクロール中の負荷が下がる */
  var MODELS=TOWNV.s.map(function(rows){
   var h=rows.length, w=0, i, y, x;
   for(i=0;i<h;i++) if(rows[i].length>w) w=rows[i].length;
   var g=[];
   for(y=0;y<h;y++){
    var r=rows[y], line=[];
    for(x=0;x<w;x++){
     var c=x<r.length?r.charAt(x):'.';
     line.push((c==='.'||c===' ')?null:(PAL[c]||'#A8BECC'));
    }
    g.push(line);
   }
   var bs=[];
   for(y=0;y<h;y++){
    for(x=0;x<w;){
     var col=g[y][x];
     if(!col){x++;continue;}
     var x1=x+1; while(x1<w&&g[y][x1]===col) x1++;
     var y1=y+1;
     for(;y1<h;y1++){
      var ok=true;
      for(var xx=x;xx<x1;xx++) if(g[y1][xx]!==col){ok=false;break;}
      if(!ok) break;
     }
     for(var yy=y;yy<y1;yy++) for(var xx2=x;xx2<x1;xx2++) g[yy][xx2]=null;
     bs.push([x,x1,y,y1,col]);
     x=x1;
    }
   }
   return {w:w,h:h,bs:bs};
  });

  /* 左向きに進むときに使う、左右を反転した絵。
     まとめた四角(bs)の x をそのまま折り返せばよい。
     行列で反転しないのは、面の向きが裏返って光が逆になるため */
  var MIR={};
  function mirror(mi){
   var g=MIR[mi];
   if(g) return g;
   var m=MODELS[mi], w=m.w, bs=[];
   for(var i=0;i<m.bs.length;i++){
    var b=m.bs[i];
    bs.push([w-b[1], w-b[0], b[2], b[3], b[4]]);
   }
   return (MIR[mi]={w:w,h:m.h,bs:bs});
  }
  var MIRK=4096;                      /* 反転版の絵に振る番号のずらし幅 */

  /* 動体1体の、いまの姿と居場所を出す。立体でも2Dでも同じものを使う。
     c = [絵,x,地面y,幅,位相,-,彩度,視差層,フィラー, 動き方,区間左,区間右,速度] */
  /* 進んだ距離。止まる時間が入っていれば、その分だけ距離が伸びない */
  /* 進んだ距離。**符号つきで返す**。
     ここで Math.abs を取ると dist が常に増え、どの車も左から右へ動く。
     一方で向きは速度の符号で決めているので、v が負の車は
     「左を向いたまま右へ進む」＝バックになる（実測で86体が逆走していた） */
  function travelled(t, v, walk, rest){
   if(!(rest>0)) return t*v;
   var P=walk+rest, cyc=Math.floor(t/P), rem=t-cyc*P;
   return (cyc*walk + Math.min(rem, walk)) * v;
  }
  function charState(c,t,sc,bandTop){
   var fl=c[7]||1, gy=paraY(c[2],fl,sc);
   var mi=c[0], ox=c[1], oy=gy-bandTop, face=1;
   var mode=c[9]||0, v=c[12]||0, dist=null;
   if(mode&&c[11]>c[10]){
    var tt=t+c[4]*23.0;                /* 位相をずらして、皆が同時に動き出さないように */
    dist=travelled(tt, v, c[13]||6, c[14]||0);
    if(mode===1){                      /* 往復して歩く。端で向きが変わる */
     var span=c[11]-c[10];
     var u=((dist%(2*span))+2*span)%(2*span);
     if(u<span){ ox=c[10]+u; face=1; } else { ox=c[11]-(u-span); face=-1; }
    }else{                             /* 端から端へ通り抜ける */
     var L=c[11]-c[10];
     ox=c[10]+(((dist%L)+L)%L);
     face=(v<0)?-1:1;
    }
   }
   var frames=TOWNV.fr&&TOWNV.fr[String(c[0])];
   if(frames){
    var step;
    if(dist===null){
     /* 揺らめき（炎・湯気・葉）は260ms/コマ。建ち上がりだけ900ms/コマでゆっくり */
     var per=(SLOWS.indexOf(c[0])>=0)?0.9:0.26;
     step=Math.floor(t/per+c[4]*2)%frames.length;
    }else{
     /* 進んだ距離でコマを決める。速さと歩幅が自動で合い、
        止まっているあいだは足も止まる */
     var stride=Math.max(6, c[3]*0.34);
     step=Math.floor(dist/stride+c[4]*2)%frames.length;
    }
    if(step<0) step+=frames.length;
    mi=frames[step];
    oy+=(step%2);                      /* コマに合わせた1pxの段差 */
   }
   if(!mode&&!frames&&!c[8]) oy+=Math.sin(t*2.1+c[4])*(1.2+c[3]*0.05);
   /* c[8] は「その場に据える（跳ねない）」という意味だけ。
      以前はここでコマ0に固定していたので、焚き火も湯気も木の揺れも
      1枚も動いていなかった */
   var model=MODELS[mi];
   var isHanabi=(model.h<=8);
   if(face<0&&!isHanabi){ model=mirror(mi); mi+=MIRK; }
   return {mi:mi, m:model, dep:isHanabi?1:DEPTH, ox:ox, oy:oy, w:c[3],
           sat:c[6], fade:(fl<1)?(1-fl)*0.75:0, hanabi:isHanabi, fl:fl, key:gy};
  }

  var FLOATS=[];                      /* 空に浮かぶ絵（スカイランタン）。buildPlacesで入る */
  var SLOWS=[];                       /* 建ち上がり。ゆっくり回す */
  var NBLD=TOWNV.nb||11;              /* ここから先が人や動物 */
  var sides=[{el:boxesL,side:0,pl:[],chs:[]},{el:boxesR,side:1,pl:[],chs:[]}];
  var twcEl=document.querySelector('.twc');
  if(twcEl){ sides.push({el:twcEl,side:2,pl:[],chs:[],mid:1}); }
  function midW(){ var w=document.getElementById('world'); return w?w.offsetWidth:1040; }

  /* 章の位置は組んでみないと分からないので実行時に測る */
  function topInWorld(el){
   var W=document.getElementById('world'), y=0, n=el;
   while(n&&n!==W){ y+=n.offsetTop; n=n.offsetParent; }
   return y;
  }
  /* 章ごとに、その章の建物だけを置いていく */
  function buildPlaces(){
   sides[0].pl=[]; sides[1].pl=[];
   sides[0].chs=[]; sides[1].chs=[];
   if(sides[2]){ sides[2].pl=[]; sides[2].chs=[]; }
   if(!window.TOWNSC) return;
   var secs={}, all=document.querySelectorAll('section[data-chname]');
   for(var q=0;q<all.length;q++){
    var nm=all[q].getAttribute('data-chname').split('\u3000')[0];
    secs[nm]={top:topInWorld(all[q]),H:all[q].offsetHeight,sat:1};
   }
   for(var ti=0;ti<TOWNS.length;ti++){
    if(secs[TOWNS[ti].n]) secs[TOWNS[ti].n].sat=TOWNS[ti].s==null?1:TOWNS[ti].s;
   }
   function satAt(sec,gy){
    var sv=sec.sat;
    if(Array.isArray(sv)) return sv[0]+(sv[1]-sv[0])*Math.min(1,Math.max(0,(gy-sec.top)/sec.H));
    return sv;
   }
   var sceneBands=[[],[]];          /* フィラーが避ける帯 */
   /* 歩く絵・走る絵の番号（build_site5 が出す） */
   var MV=(window.TOWNV&&TOWNV.mv)||{w:[],d:[]};
   var MVW=MV.w||[], MVD=MV.d||[];
   var seedM=1777;
   function rndM(){ seedM=(seedM*1103515245+12345)&0x7FFFFFFF; return seedM/0x7FFFFFFF; }
   function isMove(k){ return MVW.indexOf(k)>=0?1:(MVD.indexOf(k)>=0?2:0); }
   FLOATS=MV.f||[]; SLOWS=MV.sl||[];
   /* --- 手置きの場面（仕様の座標をそのまま使う） --- */
   for(var si=0;si<TOWNSC.length;si++){
    var sc=TOWNSC[si], sec=secs[sc.n];
    if(!sec) continue;
    for(var ii=0;ii<sc.it.length;ii++){
     var it=sc.it[ii];
     var k=it[0], u=it[1], sd=it[2], cx=it[3], scl=it[4], fl=it[5];
     var gy=(sec.top+u*sec.H)|0;
     var w=(50*scl)|0;
     var ox=(sd===0)?(440-cx-(w>>1)):(cx-(w>>1));
     var sat=satAt(sec,gy);
     sceneBands[sd].push(gy);
     if(k<13){ sides[sd].pl.push([k,ox,gy,w,sat,fl]); }
     else{
      var kk=k-NBLD;
      var mv=(kk===4||kk===5)?1:0;   /* 場面内の乗り物は右向きに走らせない→静止 */
      sides[sd].chs.push([k,ox,gy,w,(si*7+ii)*1.7%6.283,0,sat,fl]);
     }
    }
   }
   /* --- 随伴プロップ: 大きめのアンカーの周りに遠景の木や旗を自動で添える --- */
   var seedE=311;
   function rndE(){ seedE=(seedE*1103515245+12345)&0x7FFFFFFF; return seedE/0x7FFFFFFF; }
   for(var sd0=0;sd0<2;sd0++){
    var base=sides[sd0].pl.slice();
    for(var bi=0;bi<base.length;bi++){
     var b0=base[bi];
     if(b0[3]<70) continue;                      /* 幅70px以上=アンカー */
     var np=2+((rndE()*2)|0);
     for(var pi=0;pi<np;pi++){
      var pk=[23,20,21,23][(rndE()*4)|0];        /* 木/のぼり/看板/木 */
      var off=(rndE()<0.5?-1:1)*(50+rndE()*90);
      var pw=(28+rndE()*18)|0;
      var pox=Math.max(4,Math.min(436-pw,b0[1]+(b0[3]>>1)+off-(pw>>1)));
      var pgy=b0[2]-(6+rndE()*14)|0;
      sides[sd0].chs.push([pk,pox,pgy,pw,rndE()*6.283,0,b0[4],0.62,1]);
     }
    }
   }
   /* --- 遠景の街並み: 章の帯に沿って小さな建物列を敷く（y-n10の密度） --- */
   for(var ti2=0;ti2<TOWNS.length;ti2++){
    var st2=TOWNS[ti2], sec3=secs[st2.n];
    if(!sec3) continue;
    if(st2.n==='序章'||st2.n==='2019年9月') continue;
    var pool=(st2.k||[]).concat([23]);
    var step=650;
    for(var yy=sec3.top+380;yy<sec3.top+sec3.H-380;yy+=step*(0.8+rndE()*0.5)){
     var sd3=(rndE()<0.5)?0:1;
     var cnt3=3+((rndE()*3)|0);
     var x3=170+rndE()*90;
     for(var c3=0;c3<cnt3;c3++){
      var k3=pool[(rndE()*pool.length)|0];
      var w3=(24+rndE()*22)|0;
      var cx3=x3; x3+=w3*0.72+rndE()*14;
      if(cx3>388) break;
      var ox3=(sd3===0)?(440-cx3-(w3>>1)):(cx3-(w3>>1));
      var gy3=(yy+(rndE()-0.5)*60)|0;
      if(k3<13){ sides[sd3].pl.push([k3,ox3,gy3,w3,satAt(sec3,gy3),0.62]); }
      else{
       /* スカイランタンは空に浮かぶ。地面の高さから持ち上げる */
       if(FLOATS.indexOf(k3)>=0) gy3-=(90+rndE()*260)|0;
       sides[sd3].chs.push([k3,ox3,gy3,w3,rndE()*6.283,0,satAt(sec3,gy3),0.62,1]);
      }
     }
    }
   }
   /* --- フィラー: 900px超の空白にだけ、1体/900px、決定論 --- */
   var wtop=0, wbot=0;
   var wEl=document.getElementById('world');
   wbot=wEl?wEl.offsetHeight:60000;
   /* 木/看板/のぼり/軽トラ/プラレール。
      企画の絵はここに入れない（全章にばらまかれ、災害支援の給水タンクが
      第一章に出るような配置になっていた） */
   var FILL=[23,21,20,17,18];
   var seed=97;
   function rnd(){ seed=(seed*1103515245+12345)&0x7FFFFFFF; return seed/0x7FFFFFFF; }
   var lastSide=0, lastY=[-9999,-9999], run=0;
   /* 章ごとに、fillerを許す章だけ */
   var NOFILL={'序章':1,'2019年9月':1,'結び':1};
   for(var nm in secs){
    if(NOFILL[nm]) continue;
    var sec2=secs[nm];
    var bands=sceneBands[0].concat(sceneBands[1]).filter(function(y){return y>=sec2.top&&y<=sec2.top+sec2.H;});
    bands.sort(function(a,b){return a-b;});
    var edges=[sec2.top].concat(bands).concat([sec2.top+sec2.H]);
    for(var e=0;e<edges.length-1;e++){
     var a=edges[e]+300, b=edges[e+1]-300;
     if(b-a<450) continue;
     var count=Math.min(3,((b-a)/450)|0);
     for(var c2=0;c2<count;c2++){
      var gy2=(a+(b-a)*(0.3+0.4*rnd())+c2*430)|0;
      var sd2=(rnd()<0.5)?0:1;
      if(sd2===lastSide){ run++; if(run>2){ sd2=1-sd2; run=0; } } else run=0;
      if(Math.abs(gy2-lastY[sd2])<500) continue;
      lastSide=sd2; lastY[sd2]=gy2;
      var k2=FILL[(rnd()*FILL.length)|0];
      var scl2=0.6+rnd()*0.25;
      var cx2=(rnd()<0.34)?(340+rnd()*30):(200+rnd()*140);
      var w2=(50*scl2)|0;
      var ox2=(sd2===0)?(440-cx2-(w2>>1)):(cx2-(w2>>1));
      var fl2=(rnd()<0.5)?0.62:1.0;
      if(FLOATS.indexOf(k2)>=0) gy2-=(90+rnd()*260)|0;
      sides[sd2].chs.push([k2,ox2,gy2,w2,rnd()*6.283,0,satAt(sec2,gy2),fl2,1]);
     }
    }
   }
   /* --- 通りを行き来する人と、走り抜ける車 --- */
   if(MVW.length||MVD.length){
    for(var nm4 in secs){
     var s4=secs[nm4];
     for(var y4=s4.top+150; y4<s4.top+s4.H-150; y4+=230*(0.7+rndM()*0.66)){
      for(var sd4=0; sd4<2; sd4++){
       if(rndM()<0.09) continue;                 /* たまに間引いて並びを崩す */
       var car=(rndM()<0.30)&&MVD.length;
       var pool4=car?MVD:(MVW.length?MVW:MVD);
       var k4=pool4[(rndM()*pool4.length)|0];
       var m4=MODELS[k4];
       if(!m4) continue;
       var h4=car?(26+rndM()*18):(30+rndM()*15);
       var w4=Math.max(14,Math.round(h4*m4.w/m4.h));
       if(w4>300) continue;                      /* 帯より大きいものは置かない */
       var gy4=(y4+(rndM()-0.5)*90)|0;
       var fl4=(rndM()<0.40)?0.62:1.0;
       var sat4=satAt(s4,gy4), ph4=rndM();
       if(car){
        var v4=(40+rndM()*56)*((rndM()<0.5)?-1:1);
        sides[sd4].chs.push([k4,0,gy4,w4,ph4,0,sat4,fl4,0, 2, -w4-30, 470, v4]);
       }else{
        var a4=6+rndM()*110;
        var b4=Math.min(434-w4, a4+150+rndM()*190);
        if(b4-a4<70) continue;
        sides[sd4].chs.push([k4,a4,gy4,w4,ph4,0,sat4,fl4,0, 1, a4, b4, 9+rndM()*15,
                             5+rndM()*7, (rndM()<0.45)?(1.5+rndM()*3.5):0]);
       }
      }
     }
    }
   }

   /* --- 章の場面: その章でやったことを、まとまりで置く ---
      1体ずつ散らすと「街の飾り」になってしまう。同じ地面の高さに
      2〜4体を並べて、ひとつの場面として読めるようにする。
      置いたものは横に動かない。動くのは炎・湯気・提灯と、建ち上がりだけ */
   var CP=(window.TOWNV&&TOWNV.cp)||{};
   var seedS=613;
   function rndS(){ seedS=(seedS*1103515245+12345)&0x7FFFFFFF; return seedS/0x7FFFFFFF; }
   for(var nmS in secs){
    var cpS=CP[nmS];
    if(!cpS||!cpS.length) continue;
    var secS=secs[nmS];
    var ground=[], sky=[];
    for(var q1=0;q1<cpS.length;q1++){
     (FLOATS.indexOf(cpS[q1])>=0?sky:ground).push(cpS[q1]);
    }
    var STEP=760;
    for(var yS=secS.top+380; yS<secS.top+secS.H-380; yS+=STEP*(0.78+rndS()*0.5)){
     var sdS=(rndS()<0.5)?0:1;
     var gyS=(yS+(rndS()-0.5)*90)|0;
     var satS=satAt(secS,gyS);
     var flS=(rndS()<0.34)?0.62:1.0;
     if(ground.length){
      /* 地面の場面。左から順に並べる。重ならないように幅ぶん送る */
      var cntS=2+((rndS()*3)|0);
      var xS=120+rndS()*80;
      for(var iS=0;iS<cntS;iS++){
       var kS=ground[(rndS()*ground.length)|0];
       var mS=MODELS[kS];
       if(!mS) continue;
       var hS=(30+rndS()*20)*(flS<1?0.8:1);
       var wS=Math.max(16,Math.round(hS*mS.w/mS.h));
       if(xS+wS>418) break;
       var oxS=(sdS===0)?(440-xS-wS):xS;
       /* 手前に置くものほど少し下。奥行きが出る */
       sides[sdS].chs.push([kS,oxS,gyS+((iS%2)?6:0),wS,rndS()*6.283,0,satS,flS,1]);
       xS+=wS+10+rndS()*16;      /* 重ねない。隣に置く */
      }
     }
     if(sky.length&&rndS()<0.55){
      /* 空の場面。スカイランタンをまとめて浮かべる */
      var nSky=2+((rndS()*4)|0);
      for(var jS=0;jS<nSky;jS++){
       var kk=sky[(rndS()*sky.length)|0];
       var mk=MODELS[kk];
       if(!mk) continue;
       var hk=14+rndS()*16;
       var wk=Math.max(8,Math.round(hk*mk.w/mk.h));
       var xk=40+rndS()*(360-wk);
       var oxk=(sdS===0)?(440-xk-wk):xk;
       sides[sdS].chs.push([kk,oxk,(gyS-120-rndS()*300)|0,wk,rndS()*6.283,0,satS,
                            (rndS()<0.6)?0.62:1.0,1]);
      }
     }
    }
   }
   sides[0].pl.sort(function(a,b){return (a[5]-b[5])||(a[2]-b[2]);});
   sides[1].pl.sort(function(a,b){return (a[5]-b[5])||(a[2]-b[2]);});
   sides[0].chs.sort(function(a,b){return (a[7]-b[7])||(a[2]-b[2]);});
   sides[1].chs.sort(function(a,b){return (a[7]-b[7])||(a[2]-b[2]);});
   /* ---- 中央の列の余白（実測）に、設計 TOWNCC のスプライトを置く ---- */
   if(sides[2]&&window.TOWNCC&&TOWNCC.length){
    var md=sides[2], Wp=midW(), narrow=Wp<520;
    function secByLabel(lb){
     lb=lb.split('（')[0].split('　')[0];
     if(lb==='KV') return document.querySelector('section.kv');
     var all2=document.querySelectorAll('section[data-chname]');
     for(var i5=0;i5<all2.length;i5++){
      if(all2[i5].getAttribute('data-chname').indexOf(lb)===0) return all2[i5];
     }
     return null;
    }
    function zoneOf(sec,pos){
     var st=topInWorld(sec), sh=sec.offsetHeight, kids=[];
     for(var i6=0;i6<sec.children.length;i6++){
      var e=sec.children[i6];
      if(!e.offsetHeight) continue;
      var ps=getComputedStyle(e).position;
      if(ps==='absolute'||ps==='fixed') continue;
      kids.push([topInWorld(e),topInWorld(e)+e.offsetHeight]);
     }
     if(!kids.length) return null;
     kids.sort(function(a,b){return a[0]-b[0];});
     if(pos==='top') return [st,kids[0][0]];
     var mx=st;
     for(var j6=0;j6<kids.length;j6++) mx=Math.max(mx,kids[j6][1]);
     return [mx,st+sh];
    }
    for(var c9=0;c9<TOWNCC.length;c9++){
     var sl=TOWNCC[c9], sec9=secByLabel(sl.ch);
     if(!sec9) continue;
     var z9=zoneOf(sec9,sl.pos);
     if(!z9||z9[1]-z9[0]<44) continue;
     var zh=z9[1]-z9[0];
     var key9=(sec9.getAttribute('data-chname')||'').split('\u3000')[0];
     for(var i9=0;i9<sl.it.length;i9++){
      var it9=sl.it[i9];             /* [絵,x0-1,高さpx,優先度] */
      if(narrow&&it9[3]>1) continue;
      var m9=MODELS[it9[0]];
      if(!m9) continue;
      var h9=Math.min(it9[2],zh-16);
      if(narrow) h9=Math.round(h9*0.82);
      if(h9<20) continue;
      var w9=Math.round(h9*m9.w/m9.h);
      var ox9=Math.round(it9[1]*Wp-w9/2);
      ox9=Math.max(4,Math.min(Wp-w9-4,ox9));
      /* 足元は帯の太さの1/4だけ持ち上げる。端ぴったりに立てると
         次の章や世界直下の一行（出典など）に触れて見える */
      var lift9=Math.max(10,Math.min(36,Math.round(zh*0.25)));
      var gy9=z9[1]-lift9;
      var sat9=secs[key9]?satAt(secs[key9],gy9):1;
      if(it9[0]<NBLD){ md.pl.push([it9[0],ox9,gy9,w9,sat9,1]); }
      else{ md.chs.push([it9[0],ox9,gy9,w9,(c9*7+i9)*1.7%6.283,0,sat9,1,it9[4]?1:0]); }
     }
    }
    /* 章のあいだの余白にも、行き来する人を足す。
       余白は本文の外側だと実測済み（zoneOf）なので、字の上を横切らない */
    if(MVW.length||MVD.length){
     for(var cz=0;cz<TOWNCC.length;cz++){
      var slz=TOWNCC[cz], secz=secByLabel(slz.ch);
      if(!secz) continue;
      var zz=zoneOf(secz,slz.pos);
      if(!zz||zz[1]-zz[0]<70) continue;
      var keyz=(secz.getAttribute('data-chname')||'').split('　')[0];
      var nz=narrow?(1+((rndM()<0.4)?1:0)):(2+((rndM()<0.5)?1:0));
      for(var iz=0;iz<nz;iz++){
       var carz=(rndM()<0.26)&&MVD.length;
       var poolz=carz?MVD:(MVW.length?MVW:MVD);
       var kz=poolz[(rndM()*poolz.length)|0];
       var mz=MODELS[kz];
       if(!mz) continue;
       var hz=Math.min(carz?(28+rndM()*14):(30+rndM()*12), zz[1]-zz[0]-24);
       if(hz<20) continue;
       var wz=Math.max(14,Math.round(hz*mz.w/mz.h));
       if(wz>Wp-40) continue;
       var gyz=zz[1]-Math.max(10,Math.min(36,Math.round((zz[1]-zz[0])*0.25)));
       var satz=secs[keyz]?satAt(secs[keyz],gyz):1;
       if(carz){
        md.chs.push([kz,0,gyz,wz,rndM(),0,satz,1,0, 2, -wz-30, Wp+30,
                     (40+rndM()*46)*((rndM()<0.5)?-1:1)]);
       }else{
        var az=8+rndM()*(Wp*0.30);
        var bz=Math.min(Wp-wz-8, az+Wp*0.34+rndM()*Wp*0.26);
        if(bz-az<70) continue;
        md.chs.push([kz,az,gyz,wz,rndM(),0,satz,1,0, 1, az, bz, 10+rndM()*14,
                     5+rndM()*7, (rndM()<0.4)?(1.5+rndM()*3):0]);
       }
      }
     }
    }
    md.pl.sort(function(a,b){return a[2]-b[2];});
    md.chs.sort(function(a,b){return a[2]-b[2];});
    if(_q.get('ccdbg')!==null){
     document.title='CC pl'+md.pl.length+' chs'+md.chs.length+' | '
      +md.pl.map(function(p){return p[0]+'@'+p[2];}).join(' ')+' | '
      +md.chs.map(function(p){return p[0]+'@'+p[2];}).join(' ');
    }
   }
  }
  sides.forEach(function(sd){
   sd.cv=document.createElement('canvas');
   sd.ctx=sd.cv.getContext('2d');
   sd.cv2=document.createElement('canvas');     /* 動くものはこちら */
   sd.ctx2=sd.cv2.getContext('2d');
   sd.el.appendChild(sd.cv);
   sd.el.appendChild(sd.cv2);
   sd.gcv=document.createElement('canvas');     /* 立体はこちら（一番上） */
   sd.el.appendChild(sd.gcv);
   sd.el.classList.add('on');
   sd.top=null;
  });
  /* WebGLが取れた側だけ立体に切り替える。取れなければ従来の2Dのまま */
  var GL=null;
  if(window.TownGL && _q.get('nogl')===null){
   GL=true;
   for(var gi=0;gi<sides.length;gi++){
    sides[gi].gl=window.TownGL(sides[gi].gcv);
    if(!sides[gi].gl){ GL=false; break; }
   }
   if(!GL){ for(var gj=0;gj<sides.length;gj++){ sides[gj].gl=null;
     if(sides[gj].gcv.parentNode) sides[gj].gcv.parentNode.removeChild(sides[gj].gcv); } }
   /* GPUが混むとブラウザがコンテキストを取り上げる。落ちたら2Dへ戻す */
   if(GL) sides.forEach(function(sd){
    sd.gcv.addEventListener('webglcontextlost',function(e){ e.preventDefault(); fallback2D(); },false);
   });
  }
  function fallback2D(){
   if(!GL) return;
   GL=false;
   sides.forEach(function(sd){
    sd.gl=null;
    if(sd.gcv&&sd.gcv.parentNode) sd.gcv.parentNode.removeChild(sd.gcv);
    sd.bakeBand=undefined; sd.bakeTh=undefined; sd.bakeCv=null;
   });
   bandTop=null; lastTh=null; lastS=null;
   if(!raf) raf=requestAnimationFrame(update);
  }
  if(!GL){ sides.forEach(function(sd){
    if(sd.gcv&&sd.gcv.parentNode) sd.gcv.parentNode.removeChild(sd.gcv); }); }

  function shadow(ctx,x,y,w,fl){
   ctx.save();
   ctx.globalAlpha=0.05+0.06*fl;
   ctx.fillStyle='#FFFFFF';   /* 透明度は globalAlpha 側だけで作る（二重に掛けると1/255未満になる） */
   ctx.beginPath();
   ctx.ellipse(x,y+2,w*0.5,Math.max(3,w*0.09),0,0,6.2832);
   ctx.fill();
   ctx.restore();
  }
  function paraY(gy,fl,sc){ return gy+(sc-gy)*(1-fl)*0.38; }   /* 視差: 奥ほど遅い */
  function drawSide(sd,bandTop,bandH,th,lo,hi,sc){
   if(sd.hide) return;
   var ctx=sd.ctx;
   /* 建物はfl層ごとに一度だけ焼く。paraYの差はgyに依らないので同一fl層は剛体移動し、
      毎フレームは drawImage をずらして貼るだけで無損失。毎フレーム約700本の
      パスをラスタライズすると最密部でフレームが落ちる（実測34/152→0） */
   var needBake=(sd.bakeBand!==bandTop)||(sd.bakeTh===undefined)||Math.abs(th-sd.bakeTh)>=0.02;
   if(needBake){
    sd.bakeBand=bandTop; sd.bakeTh=th; sd.bakeS=sc;
    sd.bakeCv=sd.bakeCv||{}; sd.bakeFls=[];
    var cT=Math.cos(th), sT=Math.sin(th), cP=Math.cos(TILT), sP=Math.sin(TILT);
    var byFl={};
    for(var i=0;i<sd.pl.length;i++){
     var pl=sd.pl[i], gy=pl[2];
     /* 焼く範囲は帯全域。視界だけ焼くと、角が動かない区間で端が欠ける */
     if(gy<bandTop-420||gy>bandTop+bandH+300) continue;
     var fl=pl[5]||1, k=String(fl);
     (byFl[k]=byFl[k]||[]).push(pl);
    }
    var keys=Object.keys(byFl).sort(function(a,b){return (+a)-(+b);});
    for(var q=0;q<keys.length;q++){
     var k2=keys[q], flv=+k2, cvb=sd.bakeCv[k2];
     if(!cvb){ cvb=document.createElement('canvas'); sd.bakeCv[k2]=cvb; }
     if(cvb.width!==sd.cv.width||cvb.height!==sd.cv.height){ cvb.width=sd.cv.width; cvb.height=sd.cv.height; }
     var bctx=cvb.getContext('2d');
     bctx.setTransform(1,0,0,1,0,0);
     bctx.clearRect(0,0,cvb.width,cvb.height);
     bctx.setTransform(DPR,0,0,DPR,0,0);
     var list=byFl[k2];
     for(var a=0;a<list.length;a++){
      var p2=list[a];
      shadow(bctx,p2[1]+p2[3]/2,paraY(p2[2],flv,sc)-bandTop,p2[3],flv);
     }
     var fade=(flv<1)?(1-flv)*0.75:0;
     for(var b=0;b<list.length;b++){
      var p3=list[b];
      drawOne(bctx,MODELS[p3[0]],p3[1],paraY(p3[2],flv,sc)-bandTop,p3[3],cT,sT,cP,sP,p3[4],fade);
     }
     sd.bakeFls.push(flv);
    }
   }
   ctx.setTransform(1,0,0,1,0,0);
   ctx.clearRect(0,0,sd.cv.width,sd.cv.height);
   for(var f2=0;f2<sd.bakeFls.length;f2++){
    var flq=sd.bakeFls[f2];
    var dy=(sc-sd.bakeS)*(1-flq)*0.38;   /* 視差ぶんのずれ。fl=1は0 */
    ctx.drawImage(sd.bakeCv[String(flq)],0,Math.round(dy*DPR));
   }
  }

  function drawOne(ctx,m,ox,oy,wpx,cT,sT,cP,sP,sat,fade,dep){
   var ZD=dep||DEPTH;
   var S=wpx/m.w;                 /* 1マスあたりの大きさ */
   var cx=m.w/2, cy=m.h/2, cz=ZD/2;
   var px=ox+wpx/2, py=oy-(m.h*S)/2;   /* 足元を基準に置く */
   function pr(x,y,z){
    var X=(x-cx)*S, Y=(y-cy)*S, Z=(z-cz)*S;
    var X1=X*cT+Z*sT, Z1=-X*sT+Z*cT;
    var Y2=Y*cP-Z1*sP, Z2=Y*sP+Z1*cP;
    return [px+X1, py+Y2, Z2];
   }
   var list=[];
   for(var i=0;i<m.bs.length;i++){
    var b=m.bs[i], x0=b[0],x1=b[1],y0=b[2],y1=b[3],z0=0,z1=ZD;
    var F=[
     [[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0]],0,0,-1],
     [[[x1,y0,z1],[x0,y0,z1],[x0,y1,z1],[x1,y1,z1]],0,0,1],
     [[[x0,y0,z1],[x0,y0,z0],[x0,y1,z0],[x0,y1,z1]],-1,0,0],
     [[[x1,y0,z0],[x1,y0,z1],[x1,y1,z1],[x1,y1,z0]],1,0,0],
     [[[x0,y0,z1],[x1,y0,z1],[x1,y0,z0],[x0,y0,z0]],0,-1,0],
     [[[x0,y1,z0],[x1,y1,z0],[x1,y1,z1],[x0,y1,z1]],0,1,0]
    ];
    for(var f=0;f<6;f++){
     var nx=F[f][1],ny=F[f][2],nz=F[f][3];
     var NX=nx*cT+nz*sT, NZ=-nx*sT+nz*cT;
     var NY=ny*cP-NZ*sP, NZ2=ny*sP+NZ*cP;
     if(NZ2>=-0.001) continue;
     var q=F[f][0];
     var p0=pr(q[0][0],q[0][1],q[0][2]),p1=pr(q[1][0],q[1][1],q[1][2]),
         p2=pr(q[2][0],q[2][1],q[2][2]),p3=pr(q[3][0],q[3][1],q[3][2]);
     var lam=-(NX*LX+NY*LY+NZ2*LZ); if(lam<0)lam=0;
     list.push([(p0[2]+p1[2]+p2[2]+p3[2])/4,p0,p1,p2,p3,rgb(b[4],0.72+0.42*lam,sat,fade)]);
    }
   }
   list.sort(function(a,b){return b[0]-a[0];});
   for(var i=0;i<list.length;i++){
    var L=list[i];
    ctx.beginPath();
    ctx.moveTo(L[1][0],L[1][1]); ctx.lineTo(L[2][0],L[2][1]);
    ctx.lineTo(L[3][0],L[3][1]); ctx.lineTo(L[4][0],L[4][1]);
    ctx.closePath();
    ctx.fillStyle=L[5]; ctx.fill();
    ctx.strokeStyle=L[5]; ctx.lineWidth=.6; ctx.stroke();
   }
  }


  /* ===== WebGLで1側面ぶんを描く =====
     建物と動くものを1回のパスにまとめ、奥から順に深度の帯を割り当てる。
     配置の式は2D版の drawOne と同じなので、切り替えても位置は動かない。 */
  function glItems(sd,sc,th,t){
   var vh=innerHeight, lo=sc-vh*0.85, hi=sc+vh*0.85, out=[];
   for(var i=0;i<sd.pl.length;i++){
    var p=sd.pl[i], fl=p[5]||1, gy=paraY(p[2],fl,sc);
    if(gy<lo-260||gy>hi+220) continue;
    out.push({mi:p[0],m:MODELS[p[0]],dep:DEPTH,ox:p[1],oy:gy-bandTop,w:p[3],
              sat:p[4],fade:(fl<1)?(1-fl)*0.75:0,th:th,fl:fl,key:gy,ch:0,sh:1});
   }
   for(var j=0;j<sd.chs.length;j++){
    var c=sd.chs[j];
    if(c[2]<lo-360||c[2]>hi+240) continue;
    var q=charState(c,t,sc,bandTop);
    q.th=q.hanabi?null:(th+Math.sin(t*0.9+c[4])*0.12);
    q.ch=1; q.sh=(q.m.h>8)?1:0;
    out.push(q);
   }
   /* 奥から: 視差の層が薄いもの → 画面で上にあるもの → 建物 → 動くもの */
   out.sort(function(a,b){ return (a.fl-b.fl)||(a.key-b.key)||(a.ch-b.ch); });
   return out;
  }
  function drawSideGL(sd,sc,th,t){
   if(sd.hide||!sd.gl||bandTop===null) return;
   var it=glItems(sd,sc,th,t), N=it.length||1, i;
   var ctx=sd.ctx;                               /* 影は2Dのまま（半透明の楕円） */
   ctx.setTransform(1,0,0,1,0,0);
   ctx.clearRect(0,0,sd.cv.width,sd.cv.height);
   ctx.setTransform(DPR,0,0,DPR,0,0);
   for(i=0;i<N&&i<it.length;i++){
    var o=it[i]; if(!o.sh) continue;
    shadow(ctx,o.ox+o.w/2,o.oy,o.w,o.fl);
   }
   var cP=Math.cos(TILT), sP=Math.sin(TILT);
   sd.gl.begin(sd.gcv.width,sd.gcv.height);
   for(i=0;i<it.length;i++){
    var q=it[i];
    if(q.th===null) sd.gl.sprite(q.mi,q.m,q.dep,q.ox,q.oy,q.w,1,0,1,0,q.sat,q.fade,i,N,DPR);
    else sd.gl.sprite(q.mi,q.m,q.dep,q.ox,q.oy,q.w,
                      Math.cos(q.th),Math.sin(q.th),cP,sP,q.sat,q.fade,i,N,DPR);
   }
   sd.gl.end();
  }
  var lastTh=null, lastS=null, bandTop=null, bandH=0, raf=0;
  var forced=_q.get('vt'), fy=_q.get('wy');   /* 検証用 */
  var MT=_q.get('mt');                       /* 動きの時刻を止める（撮り比べ用） */
  function nowT(){
   if(MT!==null) return +MT;
   return ((typeof performance!=='undefined'&&performance.now)?performance.now():0)/1000;
  }

  function update(){
   raf=0;
   var vh=innerHeight;
   var s=(window.__worldS!==undefined&&fy===null)?window.__worldS:(((fy!==null)?+fy:scrollY)+vh/2);
   /* 回さず、揺らす。増え続けると横顔（輪郭色の面）ばかりになるため */
   var th=(forced!==null)?(+forced):(Math.sin(s/2600)*0.5);
   var need=false;
   if(bandTop===null||s<bandTop+vh*0.6||s>bandTop+bandH-vh*0.6){
    bandH=Math.round(vh*2.2); bandTop=Math.round(s-bandH/2); need=true;
    var hideSides=innerWidth<=900;   /* 左右の帯はCSSでも非表示。1x1にして無駄を消す */
    sides.forEach(function(sd){
     sd.hide=(!sd.mid&&hideSides)?1:0;
     if(sd.hide){ sd.cv.width=1; sd.cv.height=1; sd.cv2.width=1; sd.cv2.height=1;
      if(sd.gcv){ sd.gcv.width=1; sd.gcv.height=1; } return; }
     var wq=sd.mid?midW():440;
     sd.el.style.top=bandTop+'px';
     sd.el.style.height=bandH+'px';
     sd.cv.style.height=bandH+'px';
     sd.cv.width=Math.round(wq*DPR); sd.cv.height=Math.round(bandH*DPR);
     sd.cv2.style.height=bandH+'px';
     if(sd.gl){                                  /* 立体のときcv2は使わない */
      sd.cv2.width=1; sd.cv2.height=1;
      sd.gcv.style.height=bandH+'px';
      sd.gcv.width=Math.round(wq*DPR); sd.gcv.height=Math.round(bandH*DPR);
     }else{
      sd.cv2.width=Math.round(wq*DPR); sd.cv2.height=Math.round(bandH*DPR);
     }
    });
   }
   /* 立体のときは毎フレーム描き直せるので、角度のしきい値は要らない */
   if(GL){
    if(!need&&lastS!==null&&Math.abs(s-lastS)<0.5) return;
    lastTh=th; lastS=s;
    var tg=nowT();
    for(var g2=0;g2<sides.length;g2++) drawSideGL(sides[g2],s,th,tg);
    return;
   }
   if(!need&&lastTh!==null&&Math.abs(th-lastTh)<0.02&&lastS!==null&&Math.abs(s-lastS)<2) return;
   lastTh=th; lastS=s;
   var lo=s-vh*0.85, hi=s+vh*0.85;
   sides.forEach(function(sd){ drawSide(sd,bandTop,bandH,th,lo,hi,s); });
   /* 動体も即座に描く。キャンバスのリサイズは中身を消すので、
      次のanimTickを待つと1フレーム動体が消える（仮想時間の撮影では恒久に消える） */
   var tn=nowT();
   for(var di=0;di<sides.length;di++) drawChars(sides[di],tn);
  }
  /* 動くものだけを描く。建物は触らない */
  function drawChars(sd,t){
   if(bandTop===null||sd.hide) return;
   var ctx=sd.ctx2;
   var th=(lastTh===null)?0:lastTh;
   ctx.setTransform(1,0,0,1,0,0);
   ctx.clearRect(0,0,sd.cv2.width,sd.cv2.height);
   ctx.setTransform(DPR,0,0,DPR,0,0);
   var vh=innerHeight;
   var s=((fy!==null)?+fy:scrollY)+vh/2;
   var lo=s-vh*0.85, hi=s+vh*0.85;
   var cP=Math.cos(TILT), sP=Math.sin(TILT);
   var scNow=((fy!==null)?+fy:scrollY)+vh/2;
   var visc=[];
   for(var iv=0;iv<sd.chs.length;iv++){
    var cv2=sd.chs[iv];
    if(cv2[2]<lo-360||cv2[2]>hi+240) continue;
    visc.push(cv2);
   }
   var st=[];
   for(var is2=0;is2<visc.length;is2++) st.push(charState(visc[is2],t,scNow,bandTop));
   for(var is3=0;is3<st.length;is3++){          /* 影のパス */
    var cs=st[is3];
    if(cs.m.h>8) shadow(ctx,cs.ox+cs.w/2,cs.oy,cs.w,cs.fl);
   }
   for(var i=0;i<st.length;i++){
    var q=st[i];
    var thc=th+Math.sin(t*0.9+visc[i][4])*0.12; /* ゆっくり首を振る */
    if(q.hanabi){ drawOne(ctx,q.m,q.ox,q.oy,q.w,1,0,1,0,q.sat,q.fade,1); }
    else{ drawOne(ctx,q.m,q.ox,q.oy,q.w,Math.cos(thc),Math.sin(thc),cP,sP,q.sat,q.fade); }
   }
  }
  var animRaf=0, lastAnim=0;
  function animTick(ts){
   animRaf=requestAnimationFrame(animTick);
   if(ts-lastAnim<33) return;                   /* 30fpsまで */
   if(document.hidden) return;
   lastAnim=ts;
   var t=(MT!==null)?(+MT):(ts/1000);
   if(GL){
    if(bandTop===null) return;
    var vh2=innerHeight;
    var s2=(window.__worldS!==undefined&&fy===null)?window.__worldS:(((fy!==null)?+fy:scrollY)+vh2/2);
    var th2=(forced!==null)?(+forced):(Math.sin(s2/2600)*0.5);
    lastS=s2; lastTh=th2;
    for(var g3=0;g3<sides.length;g3++) drawSideGL(sides[g3],s2,th2,t);
    return;
   }
   for(var i=0;i<sides.length;i++) drawChars(sides[i],t);
  }
  animRaf=requestAnimationFrame(animTick);
  /* 検証用: ?wy= のときは最後に同期で描き切る。
     仮想時間の撮影では、画像ロード毎のrelayoutでbandTopがnullに戻り、
     再描画のrAFが走る前に撮影が終わって動体が消えることがある（実ブラウザでは起きない） */
  if(fy!==null){
   addEventListener('load',function(){
    setTimeout(function(){
     update();
     if(GL){
      var vh3=innerHeight, s3=(+fy)+vh3/2;
      var th3=(forced!==null)?(+forced):(Math.sin(s3/2600)*0.5);
      for(var g4=0;g4<sides.length;g4++) drawSideGL(sides[g4],s3,th3,nowT());
     }else{
      for(var i=0;i<sides.length;i++) drawChars(sides[i],nowT());
     }
    },1400);
   });
  }
  if(_q.get('mvdbg')!==null){
   setTimeout(function(){
    var vhm=innerHeight, sm=((fy!==null)?+fy:scrollY)+vhm/2, bt=bandTop||0;
    var nMove=0, nWalk=0, nCar=0, moved=0, flipped=0, samp=[];
    var nFloat=0, nProp=0, CP=(window.TOWNV&&TOWNV.cp)||{}, allcp={};
    for(var cn in CP) for(var ci=0;ci<CP[cn].length;ci++) allcp[CP[cn][ci]]=1;
    for(var k0=0;k0<sides.length;k0++){
     var L0=sides[k0].chs;
     for(var i0=0;i0<L0.length;i0++){
      if(FLOATS.indexOf(L0[i0][0])>=0) nFloat++;
      if(allcp[L0[i0][0]]) nProp++;
     }
    }
    for(var k=0;k<sides.length;k++){
     var L=sides[k].chs;
     for(var i=0;i<L.length;i++){
      var c=L[i];
      if(!c[9]) continue;
      nMove++; if(c[9]===1) nWalk++; else nCar++;
      var A=charState(c,0.0,sm,bt), B=charState(c,3.7,sm,bt);
      if(Math.abs(A.ox-B.ox)>1) moved++;
      if(A.mi!==B.mi&&(A.mi>=4096)!==(B.mi>=4096)) flipped++;
      if(samp.length<3) samp.push(c[0]+':'+Math.round(A.ox)+'->'+Math.round(B.ox));
     }
    }
    /* 企画の絵は「横に動かない」「コマは進む」の両方を実測する */
    var pStay=0, pMove=0, pAnim=0, pStill=0, stills=[];
    var rev=0, fwd=0;
    for(var s6=0;s6<sides.length;s6++){
     var C6=sides[s6].chs;
     for(var i6=0;i6<C6.length;i6++){
      var c6=C6[i6];
      if(!c6[9]) continue;
      var A6=charState(c6,1.0,sm,bt), B6=charState(c6,1.2,sm,bt);
      var d6=B6.ox-A6.ox;
      if(Math.abs(d6)<0.01||Math.abs(d6)>60) continue;
      var f6=(B6.mi>=MIRK)?-1:1;
      if(d6*f6>0) fwd++; else rev++;
     }
    }
    for(var k1=0;k1<sides.length;k1++){
     var L1=sides[k1].chs;
     for(var i1=0;i1<L1.length;i1++){
      var c1=L1[i1];
      if(!allcp[c1[0]]) continue;
      /* 2コマの絵は260ms周期なので、粗く測ると同じコマに当たる。
         0.13秒刻みで2.5秒ぶん見る（最短周期の半分より細かく） */
      var A1=charState(c1,0.0,sm,bt), mvd=0, seen={};
      for(var tt1=0;tt1<=2.5;tt1+=0.13){
       var S1=charState(c1,tt1,sm,bt);
       if(Math.abs(A1.ox-S1.ox)>0.01) mvd=1;
       seen[S1.mi]=1;
      }
      if(mvd) pMove++; else pStay++;
      var fr1=TOWNV.fr&&TOWNV.fr[String(c1[0])];
      if(fr1){ if(Object.keys(seen).length>1) pAnim++;
               else { pStill++; if(stills.indexOf(c1[0])<0) stills.push(c1[0]); } }
     }
    }
    /* 重なりを数える。画面上の箱が6割以上かぶっている組を「重なり」とする */
    var ov=0, pairs=0;
    for(var s5=0;s5<sides.length;s5++){
     var L5=[], C5=sides[s5].chs;
     for(var i5=0;i5<C5.length;i5++){
      var q5=charState(C5[i5],1.5,sm,bt);
      if(q5.oy<-400||q5.oy>4000) continue;
      L5.push([q5.ox,q5.oy-q5.m.h*(q5.w/q5.m.w),q5.w,q5.m.h*(q5.w/q5.m.w),C5[i5][7]||1]);
     }
     for(var a5=0;a5<L5.length;a5++) for(var b5=a5+1;b5<L5.length;b5++){
      var A5=L5[a5], B5=L5[b5];
      if(A5[4]!==B5[4]) continue;              /* 層が違えば重なって良い */
      var ix=Math.min(A5[0]+A5[2],B5[0]+B5[2])-Math.max(A5[0],B5[0]);
      var iy=Math.min(A5[1]+A5[3],B5[1]+B5[3])-Math.max(A5[1],B5[1]);
      pairs++;
      if(ix>0&&iy>0){
       var ar=ix*iy, sm5=Math.min(A5[2]*A5[3],B5[2]*B5[3]);
       if(sm5>0&&ar/sm5>0.2) ov++;   /* 2割かぶったら重なりとみなす */
      }
     }
    }
    document.title='向きと進行が一致='+fwd+' 逆走='+rev+' / 重なり='+ov+'組 / MV 動く絵='+nMove+' 実際に動いた='+moved+' 反転='+flipped
      +' ／ 企画の絵='+nProp+' 横に動かない='+pStay+' 動いた='+pMove
      +' コマが進む='+pAnim+' 止まったまま='+pStill+'（絵'+stills.join(',')+'） 浮かぶ='+nFloat;
   },2600);
  }
  if(_q.get('glbench')!==null){
   setTimeout(function(){
    var vhb=innerHeight, sb=((fy!==null)?+fy:scrollY)+vhb/2;
    var thb=Math.sin(sb/2600)*0.5, k, t0, n=60, cnt=0;
    if(GL){
     for(k=0;k<sides.length;k++) cnt+=glItems(sides[k],sb,thb,1.5).length;
     t0=performance.now();
     for(k=0;k<n;k++) for(var j=0;j<sides.length;j++) drawSideGL(sides[j],sb,thb,k*0.033);
     if(sides[0].gl){ var g0=sides[0].gl.gl; g0.finish&&g0.finish(); }
    }else{
     for(k=0;k<sides.length;k++){ var lo9=sb-vhb*0.85, hi9=sb+vhb*0.85;
      for(var m9=0;m9<sides[k].chs.length;m9++){ var c9=sides[k].chs[m9];
       if(c9[2]>=lo9-360&&c9[2]<=hi9+240) cnt++; }
      for(var n9=0;n9<sides[k].pl.length;n9++) cnt++; }
     t0=performance.now();
     for(k=0;k<n;k++){ bandTop=bandTop; lastTh=null;
      for(var j2=0;j2<sides.length;j2++){ sides[j2].bakeTh=undefined;
       drawSide(sides[j2],bandTop,bandH,thb,sb-vhb,sb+vhb,sb); drawChars(sides[j2],k*0.033); } }
    }
    var ms=(performance.now()-t0)/n, tot=0, tpl=0;
    for(k=0;k<sides.length;k++){ tot+=sides[k].chs.length; tpl+=sides[k].pl.length; }
    document.title='BENCH GL='+(GL?1:0)+' 見えている絵='+cnt+' 建物計='+tpl+' 動体計='+tot
      +' bandTop='+bandTop+' vh='+vhb+' 1フレーム='+ms.toFixed(2)+'ms';
   },2600);
  }
  if(_q.get('ccpx')!==null){
   setTimeout(function(){
    function px(cv){ try{ var d=cv.getContext('2d').getImageData(0,0,cv.width,cv.height).data,n=0;
     for(var i=3;i<d.length;i+=64) if(d[i]>0) n++; return n; }catch(e){ return 'ERR'; } }
    /* WebGLの面は getImageData が使えないので readPixels で数える */
    function gpx(sd){ try{ var g=sd.gl.gl, w=sd.gcv.width, h=sd.gcv.height;
     var b=new Uint8Array(w*h*4); g.readPixels(0,0,w,h,g.RGBA,g.UNSIGNED_BYTE,b);
     var n=0; for(var i=3;i<b.length;i+=64) if(b[i]>0) n++; return n; }catch(e){ return 'ERR'; } }
    var md=sides[2];
    document.title='PX bandTop='+bandTop+' GL='+(GL?1:0)
     +' cv='+(md?md.cv.width+'x'+md.cv.height:'-')
     +(GL?(' 立体px='+gpx(md)+' 影px='+px(md.cv)+' 左立体px='+gpx(sides[0]))
         :(' 建物px='+px(md.cv)+' 動体px='+px(md.cv2)+' 左側動体px='+px(sides[0].cv2)));
   },2500);
  }

  function sched(){ if(!raf) raf=requestAnimationFrame(update); }
  function relayout(){ buildPlaces(); bandTop=null; lastTh=null; sched();
   if(_q.get('pldbg')!==null){
    var o=[];
    [10,9,0,2].forEach(function(kk){
     for(var s2=0;s2<2;s2++) sides[s2].pl.forEach(function(p){ if(p[0]===kk) o.push(kk+'@'+p[2]); });
    });
    document.title='PL '+o.join(' ');
   }
  }
  addEventListener('scroll',sched,{passive:true});
  addEventListener('resize',relayout,{passive:true});
  addEventListener('load',relayout);
  /* 画像が入って章の高さが変わるので測り直す */
  if(window.ResizeObserver){
   var wro=new ResizeObserver(function(){ relayout(); });
   wro.observe(document.getElementById('world'));
  }
  relayout();
 }catch(e){}
})();


/* ===== つづきを読む（ダイジェストの開閉） ===== */
document.addEventListener('click',function(e){
 var b=e.target.closest&&e.target.closest('.morebtn');
 if(!b) return;
 var sec=b.closest('section');
 if(!sec) return;
 var open=sec.classList.toggle('open');
 b.textContent=open?'たたむ':'つづきを読む';
});


/* ===== シェアのリンクを、いま見ているURLで組む（JSなしでも静的URLで動く） ===== */
(function(){
 try{
  var u=location.origin+location.pathname;
  var x=document.querySelector('a[data-s="x"]');
  if(x) x.href='https://twitter.com/intent/tweet?url='+encodeURIComponent(u);
  var ln=document.querySelector('a[data-s="line"]');
  if(ln) ln.href='https://social-plugins.line.me/lineit/share?url='+encodeURIComponent(u);
 }catch(e){}
})();
